          CLRA                            ; 48A5: 4F            clear durations, rests, patterns and bend
          CLRB                            ; 48A6: 5F
          STA    <VOICE1+V_DUR            ; 48A7: 97 1F
          STA    <VOICE1+V_GAP            ; 48A9: 97 20
          STD    <VOICE1+V_PATPTR         ; 48AB: DD 1B
          STD    <VOICE1+V_BEND           ; 48AD: DD 22
          STD    <VOICE1+V_BRATE          ; 48AF: DD 24
          STA    <VOICE2+V_DUR            ; 48B1: 97 31
          STA    <VOICE2+V_GAP            ; 48B3: 97 32
          STD    <VOICE2+V_PATPTR         ; 48B5: DD 2D
          STD    <VOICE2+V_BEND           ; 48B7: DD 34
          STD    <VOICE2+V_BRATE          ; 48B9: DD 36
          STA    <VOICE3+V_DUR            ; 48BB: 97 43
