          STA    <VOICE3+V_GAPLEN         ; 48CB: 97 45
          LDD    #INSTRS                  ; 48CD: CC 4B AD      all voices start on instrument 0
          STD    <VOICE1+V_INSTR          ; 48D0: DD 16
          STD    <VOICE2+V_INSTR          ; 48D2: DD 28
