          JSR    <MIXER                   ; 48DA: 9D EA
          JSR    PWMSTEP                  ; 48DC: BD 4A 81
          JSR    <MIXER                   ; 48DF: 9D EA
          JSR    PWMSTEP                  ; 48E1: BD 4A 81
