          ROLA                            ; 4907: 49
          STD    V1_FREQ                  ; 4908: FD 49 58      patch the sample loop
          LDD    <VOICE1+V_BEND           ; 490B: DC 22         advance the bend
          ADDD   <VOICE1+V_BRATE          ; 490D: D3 24
          STD    <VOICE1+V_BEND           ; 490F: DD 22
          LDX    <VOICE2+V_INSTR          ; 4911: 9E 28         voice 2, the same without bend
          LDA    <VOICE2+V_FRAME          ; 4913: 96 2C
          LEAX   A,X                      ; 4915: 30 86
          LDU    ,X++                     ; 4917: EE 81         U = voice 2 wave
          LDB    ,X                       ; 4919: E6 84
          ADDA   #$04                     ; 491B: 8B 04
          STA    <VOICE2+V_FRAME          ; 491D: 97 2C
          LDX    #FREQTAB                 ; 491F: 8E 53 2D
          ADDB   <VOICE2+V_NOTE           ; 4922: DB 27
          ABX                             ; 4924: 3A
          LDD    ,X                       ; 4925: EC 84
          ASLB                            ; 4927: 58
          ROLA                            ; 4928: 49
