          LDX    <VOICE3+V_INSTR          ; 492C: 9E 3A         voice 3
          LDA    <VOICE3+V_FRAME          ; 492E: 96 3E
          LEAX   A,X                      ; 4930: 30 86
          LDS    ,X++                     ; 4932: 10 EE 81      S = voice 3 wave
          LDB    ,X                       ; 4935: E6 84
          ADDA   #$04                     ; 4937: 8B 04
          STA    <VOICE3+V_FRAME          ; 4939: 97 3E
          LDX    #FREQTAB                 ; 493B: 8E 53 2D
          ADDB   <VOICE3+V_NOTE           ; 493E: DB 39
