; SAMPLOOP: 77 cycles per sample. Each voice's 16-bit phase lives in
; the operand of its LDD: add the frequency, store the result back
; into the LDD, then index the wave with the phase high byte. A is a
; signed index, which is why wave pointers aim at the middle of each
; table. Voice 1 and 2 samples are stored into the two ADDB operands,
; so the three are summed and sent to the DAC with no extra loads.
; Author's name: synth_mixer.
SAMPLOOP  LDD    #$0000                   ; 4954: CC 00 00      voice 1 phase
          ADDD   #$0000                   ; 4957: C3 00 00      + frequency (from MIXER)
          STD    <V1_PHASE                ; 495A: DD 55         store the new phase
          LDB    A,Y                      ; 495C: E6 A6         sample = wave[phase high]
          STB    <V1_SAMPLE               ; 495E: D7 77         into the first ADDB
          LDD    #$0000                   ; 4960: CC 00 00      voice 2 phase
          ADDD   #$0000                   ; 4963: C3 00 00      + frequency
          STD    <V2_PHASE                ; 4966: DD 61         store the new phase
          LDB    A,U                      ; 4968: E6 C6         sample
          STB    <V2_SAMPLE               ; 496A: D7 79         into the second ADDB
          LDD    #$0000                   ; 496C: CC 00 00      voice 3 phase
          ADDD   #$0000                   ; 496F: C3 00 00      + frequency
          STD    <V3_PHASE                ; 4972: DD 6D         store the new phase
          LDB    A,S                      ; 4974: E6 E6         voice 3 sample
          ADDB   #$00                     ; 4976: CB 00         + voice 1 sample
          ADDB   #$00                     ; 4978: CB 00         + voice 2 sample
          STB    ,X                       ; 497A: E7 84         out to the DAC
