          LDX    #PATTERNS-2              ; 49D7: 8E 55 3B      patterns count from 1
          ASLB                            ; 49DA: 58
          ABX                             ; 49DB: 3A
          LDX    ,X                       ; 49DC: AE 84
          STX    V_PATPTR,U               ; 49DE: AF 46
