          ASLB                            ; 49EC: 58
          CLRA                            ; 49ED: 4F
          ADDD   #CMDTABLE                ; 49EE: C3 49 F7      index the BRA table
          STD    <DISPATCH                ; 49F1: DD 06
          JMP    [DISPATCH]               ; 49F3: 6E 9F 48 06   handler; X is past the command

; CMDTABLE: pattern commands. Command byte n jumps via entry n.
;   0                  end of pattern: fetch the next from the song list
;   1                  no operation
;   2 i (w p) x 15     define instrument i: 15 frames of wave, pitch
;   3 n d r            note n: sounds d ticks, then r ticks of release
;                      and rest. r = 0 ties it to the next note, which
;                      then continues the envelope instead of restarting.
;   4, 5, 6 i          select instrument i for the following notes
;   7 x hh ll          set the pitch bend (x ignored)
;   8 x hh ll          set the bend rate (x ignored)
; Only voice 1 applies bend. Command 3 ends the voice's tick; all the
; others run the next command straight away.
; Author's name: cmd_jumptable.
CMDTABLE  BRA    C_ENDPAT                 ; 49F7: 20 14         0: end of pattern

          BRA    C_NOP                    ; 49F9: 20 14         1: no operation

          BRA    C_DEFINS                 ; 49FB: 20 16         2: define instrument

          BRA    C_NOTE                   ; 49FD: 20 3F         3: note

          BRA    C_SETINS                 ; 49FF: 20 64         4: (unused) same as 6

          BRA    C_SETINS                 ; 4A01: 20 62         5: (unused) same as 6

          BRA    C_SETINS                 ; 4A03: 20 60         6: select instrument

          BRA    C_BEND                   ; 4A05: 20 6A         7: set pitch bend

          BRA    C_BRATE                  ; 4A07: 20 70         8: set bend rate

; CMDNEXT: save the pattern pointer and run the next command now.
; Author's name: command_done.
CMDNEXT   STX    V_PATPTR,U               ; 4A09: AF 46
          BRA    SEQVOICE                 ; 4A0B: 20 B5

C_ENDPAT  BRA    NEXTPAT                  ; 4A0D: 20 B7

C_NOP     LDA    #$01                     ; 4A0F: 86 01         (A is not used)
          BRA    CMDNEXT                  ; 4A11: 20 F6

; C_DEFINS: command 2. Builds instrument i at INSTRS + 60*i. Waves
; 16-23 (noise) are pitched down 40 notes.
; Author's name: command_02.
C_DEFINS  PSHS   U                        ; 4A13: 34 40
          LDA    #$3C                     ; 4A15: 86 3C         60 bytes per instrument
          LDB    ,X+                      ; 4A17: E6 80
          MUL                             ; 4A19: 3D
          ADDD   #INSTRS                  ; 4A1A: C3 4B AD
          TFR    D,Y                      ; 4A1D: 1F 02
          LDA    #$0F                     ; 4A1F: 86 0F         15 frames
          STA    <CMD2COUNT               ; 4A21: 97 03
L4A23     LDD    ,X++                     ; 4A23: EC 81         A = wave, B = pitch offset
          CMPA   #$10                     ; 4A25: 81 10         noise wave?
          BLT    L4A2B                    ; 4A27: 2D 02
          SUBB   #$28                     ; 4A29: C0 28         pitch it down 40 notes
L4A2B     ASLA                            ; 4A2B: 48
          LDU    #WAVEPTRS                ; 4A2C: CE 4B 7D      look up the wave pointer
          LDU    A,U                      ; 4A2F: EE C6
          STU    ,Y++                     ; 4A31: EF A1         frame +0: wave pointer
          ASLB                            ; 4A33: 58            frame +2: pitch times 2
          STB    ,Y++                     ; 4A34: E7 A1         (+3 is skipped)
          DEC    <CMD2COUNT               ; 4A36: 0A 03
          BNE    L4A23                    ; 4A38: 26 E9
          PULS   U                        ; 4A3A: 35 40
          BRA    CMDNEXT                  ; 4A3C: 20 CB

; C_NOTE: command 3 n d r.
; Author's name: command_03.
C_NOTE    LDD    ,X++                     ; 4A3E: EC 81         A = note, B = duration
          ASLA                            ; 4A40: 48
          STA    ,U                       ; 4A41: A7 C4         V_NOTE: note times 2
          DECB                            ; 4A43: 5A
          STB    V_DUR,U                  ; 4A44: E7 4A         V_DUR = d - 1
          LDA    V_GAPLEN,U               ; 4A46: A6 4C         previous note had a rest?
          BEQ    L4A4F                    ; 4A48: 27 05
          CLRA                            ; 4A4A: 4F            yes: restart the envelope
          STA    V_FRAME,U                ; 4A4B: A7 45
          BRA    L4A4F                    ; 4A4D: 20 00         (branches to the next line)

L4A4F     LDA    ,X+                      ; 4A4F: A6 80         A = rest length
          STA    V_GAP,U                  ; 4A51: A7 4B
          STA    V_GAPLEN,U               ; 4A53: A7 4C
          STX    V_PATPTR,U               ; 4A55: AF 46         save the pattern pointer
          LDD    V_IBASE,U                ; 4A57: EC 43         sound the selected instrument
          STD    V_INSTR,U                ; 4A59: ED 41
          LDA    V_GAP,U                  ; 4A5B: A6 4B         with a rest: V_GAP = r - 1,
          BEQ    L4A64                    ; 4A5D: 27 05
