; PWMSTEP: pulse-width modulation of wave 13 (WPWM). Moves the edge
; at the end of the high part 4 samples per call, sweeping it back and
; forth over the second half of the table. The values written are
; already biased: $4E is the high level, $06 the low level.
; WPWM2 and WPWM4 are copies made at startup and do not sweep.
; Author's name: rect_modulator.
PWMSTEP   LDX    #WPWM                    ; 4A81: 8E 78 95      X = edge
          LDB    <PWMPOS                  ; 4A84: D6 10
          ABX                             ; 4A86: 3A
          LDA    <PWMDIR                  ; 4A87: 96 0F         direction
          BEQ    PWMGROW                  ; 4A89: 27 18
          LDA    #$06                     ; 4A8B: 86 06         shrink: write low, backwards
          STA    ,X                       ; 4A8D: A7 84
          STA    ,-X                      ; 4A8F: A7 82
          STA    ,-X                      ; 4A91: A7 82
          STA    ,-X                      ; 4A93: A7 82
          SUBB   #$04                     ; 4A95: C0 04
          STB    <PWMPOS                  ; 4A97: D7 10
          CMPB   #$7F                     ; 4A99: C1 7F         back to the middle?
          BNE    L4ABB                    ; 4A9B: 26 1E
          LDA    #$00                     ; 4A9D: 86 00         turn round
          LDB    #$80                     ; 4A9F: C6 80
          BRA    L4AB7                    ; 4AA1: 20 14

PWMGROW   LDA    #$4E                     ; 4AA3: 86 4E         grow: write high, forwards
          STA    ,X+                      ; 4AA5: A7 80
          STA    ,X+                      ; 4AA7: A7 80
          STA    ,X+                      ; 4AA9: A7 80
          STA    ,X                       ; 4AAB: A7 84
          ADDB   #$04                     ; 4AAD: CB 04
          STB    <PWMPOS                  ; 4AAF: D7 10
          BNE    L4ABB                    ; 4AB1: 26 08         wrapped past the end?
          LDA    #$FF                     ; 4AB3: 86 FF         turn round
          LDB    #$FF                     ; 4AB5: C6 FF
L4AB7     STB    <PWMPOS                  ; 4AB7: D7 10
          STA    <PWMDIR                  ; 4AB9: 97 0F
L4ABB     RTS                             ; 4ABB: 39

; MAKEWAVES: build the 256-byte signed wave tables. Full amplitude
; is about +/-42 ($24/$DC for the pulses). Half and quarter
; amplitude copies give the volume steps. Finally $2A is added to
; every byte, so the sum of three voices centres on the DAC's middle.
; Author's name: generate_waveform.
MAKEWAVES LDX    #WPULSE                  ; 4ABC: 8E 75 95      WPULSE: 224 high
          LDA    #$E0                     ; 4ABF: 86 E0
          LDB    #$24                     ; 4AC1: C6 24
L4AC3     STB    ,X+                      ; 4AC3: E7 80
          DECA                            ; 4AC5: 4A
          BNE    L4AC3                    ; 4AC6: 26 FB
          LDA    #$20                     ; 4AC8: 86 20         then 32 low
          LDB    #$DC                     ; 4ACA: C6 DC
L4ACC     STB    ,X+                      ; 4ACC: E7 80
          DECA                            ; 4ACE: 4A
          BNE    L4ACC                    ; 4ACF: 26 FB
          LDX    #WPWM                    ; 4AD1: 8E 78 95      WPWM: 88 low
          LDA    #$58                     ; 4AD4: 86 58
          LDB    #$DC                     ; 4AD6: C6 DC
L4AD8     STB    ,X+                      ; 4AD8: E7 80
          DECA                            ; 4ADA: 4A
          BNE    L4AD8                    ; 4ADB: 26 FB
          LDA    #$A8                     ; 4ADD: 86 A8         then 168 high
          LDB    #$24                     ; 4ADF: C6 24
L4AE1     STB    ,X+                      ; 4AE1: E7 80
          DECA                            ; 4AE3: 4A
          BNE    L4AE1                    ; 4AE4: 26 FB
          LDX    #WOFF                    ; 4AE6: 8E 6E 95      WOFF: silence
          LDA    #$00                     ; 4AE9: 86 00
          LDB    #$00                     ; 4AEB: C6 00
L4AED     STB    ,X+                      ; 4AED: E7 80
          DECA                            ; 4AEF: 4A
          BNE    L4AED                    ; 4AF0: 26 FB
          LDX    #WSINE                   ; 4AF2: 8E 6B 95      WSINE: second half is
          LDA    #$80                     ; 4AF5: 86 80         the first half negated
L4AF7     LDB    ,X+                      ; 4AF7: E6 80
          NEGB                            ; 4AF9: 50
          STB    <$7F,X                   ; 4AFA: E7 88 7F
          DECA                            ; 4AFD: 4A
          BNE    L4AF7                    ; 4AFE: 26 F7
          LDX    #WPULSE                  ; 4B00: 8E 75 95      half and quarter copies
          LDY    #WPULSE2                 ; 4B03: 10 8E 76 95
          JSR    HALVE                    ; 4B07: BD 4B 73
          LDX    #WPULSE2                 ; 4B0A: 8E 76 95
          LDY    #WPULSE4                 ; 4B0D: 10 8E 77 95
          JSR    HALVE                    ; 4B11: BD 4B 73
          LDX    #WSAW                    ; 4B14: 8E 6C 95
          LDY    #WSAW2                   ; 4B17: 10 8E 71 95
          JSR    HALVE                    ; 4B1B: BD 4B 73
          LDX    #WSAW2                   ; 4B1E: 8E 71 95
          LDY    #WSAW4                   ; 4B21: 10 8E 72 95
          JSR    HALVE                    ; 4B25: BD 4B 73
          LDX    #WTRI                    ; 4B28: 8E 6D 95
          LDY    #WTRI2                   ; 4B2B: 10 8E 73 95
          JSR    HALVE                    ; 4B2F: BD 4B 73
          LDX    #WTRI2                   ; 4B32: 8E 73 95
          LDY    #WTRI4                   ; 4B35: 10 8E 74 95
          JSR    HALVE                    ; 4B39: BD 4B 73
          LDX    #WSINE                   ; 4B3C: 8E 6B 95
          LDY    #WSINE2                  ; 4B3F: 10 8E 6F 95
          JSR    HALVE                    ; 4B43: BD 4B 73
          LDX    #WSINE2                  ; 4B46: 8E 6F 95
          LDY    #WSINE4                  ; 4B49: 10 8E 70 95
          JSR    HALVE                    ; 4B4D: BD 4B 73
          LDX    #WPWM                    ; 4B50: 8E 78 95
          LDY    #WPWM2                   ; 4B53: 10 8E 79 95
          JSR    HALVE                    ; 4B57: BD 4B 73
          LDX    #WPWM2                   ; 4B5A: 8E 79 95
          LDY    #WPWM4                   ; 4B5D: 10 8E 7A 95
          JSR    HALVE                    ; 4B61: BD 4B 73
          LDX    #WNOISE                  ; 4B64: 8E 63 95      bias every table, noise too
L4B67     LDA    ,X                       ; 4B67: A6 84
          ADDA   #$2A                     ; 4B69: 8B 2A
          STA    ,X+                      ; 4B6B: A7 80
          CMPX   #WEND                    ; 4B6D: 8C 7B 95
          BCS    L4B67                    ; 4B70: 25 F5
          RTS                             ; 4B72: 39

; HALVE: Y[i] = X[i] / 2 (signed) for 256 bytes.
; Author's name: waveform_volume_half.
HALVE     CLRA                            ; 4B73: 4F
L4B74     LDB    ,X+                      ; 4B74: E6 80
          ASRB                            ; 4B76: 57
